import type { ImgHTMLAttributes } from 'react';
import { photos, type PhotoKey } from '../../content/photos';

const BASE = import.meta.env.BASE_URL;

interface PictureProps extends Omit<ImgHTMLAttributes<HTMLImageElement>, 'src' | 'srcSet' | 'alt' | 'width' | 'height'> {
  photo: PhotoKey;
  /** `sizes` attribute – describe the rendered width */
  sizes: string;
  /** Above-the-fold image: eager + high priority */
  priority?: boolean;
  /** Override alt (e.g. '' when the image is decorative next to a caption) */
  alt?: string;
}

/** Responsive AVIF / WebP / JPEG picture generated by scripts/prepare-images.mjs */
export function Picture({ photo, sizes, priority, alt, className, style, ...rest }: PictureProps) {
  const p = photos[photo];
  const set = (ext: string) => p.widths.map((w) => `${BASE}images/${p.slug}-${w}.${ext} ${w}w`).join(', ');
  const fallback = `${BASE}images/${p.slug}-${p.widths[p.widths.length - 1]}.jpg`;
  return (
    <picture>
      <source type="image/avif" srcSet={set('avif')} sizes={sizes} />
      <source type="image/webp" srcSet={set('webp')} sizes={sizes} />
      <img
        src={fallback}
        srcSet={set('jpg')}
        sizes={sizes}
        alt={alt ?? p.alt}
        width={p.width}
        height={p.height}
        loading={priority ? 'eager' : 'lazy'}
        decoding={priority ? 'sync' : 'async'}
        fetchPriority={priority ? 'high' : undefined}
        className={className}
        style={{ objectPosition: p.focus, ...style }}
        {...rest}
      />
    </picture>
  );
}
